// Code node "Companies to research". One item per outside company on today's calendar.
const YOUR_DOMAIN = "example.com"; // your own email domain, so internal meetings are skipped
const FREE_MAIL = /^(gmail|googlemail|yahoo|hotmail|outlook|live|icloud|me|aol|proton|protonmail|gmx|mail|yandex)\./;

const byDomain = new Map();
for (const { json: ev } of $input.all()) {
  const attendees = Array.isArray(ev.attendees) ? ev.attendees : [];
  for (const a of attendees) {
    const email = String((a && a.email) || "").toLowerCase();
    const domain = email.split("@")[1] || "";
    if (!domain || domain === YOUR_DOMAIN || FREE_MAIL.test(domain) || domain.endsWith("calendar.google.com")) continue;
    const entry = byDomain.get(domain) || { domain, meetings: [], people: [] };
    const title = ev.summary || "Meeting";
    const start = (ev.start && (ev.start.dateTime || ev.start.date)) || "";
    if (!entry.meetings.some((m) => m.title === title && m.start === start)) entry.meetings.push({ title, start });
    if (!entry.people.includes(email)) entry.people.push(email);
    byDomain.set(domain, entry);
  }
}
return [...byDomain.values()].slice(0, 10).map((json) => ({ json }));

// Code node "Build the email". One email with a short brief per company, plus what it cost.
// Shared helper: adds up what the agent's looot calls cost, from the agent's intermediate steps
// (the agent's "Return Intermediate Steps" option is on). Each looot tool answer carries actualCost.
function agentCost(item) {
  const steps = (item && Array.isArray(item.intermediateSteps)) ? item.intermediateSteps : [];
  let usd = 0;
  let calls = 0;
  for (const step of steps) {
    const tool = String((step && step.action && step.action.tool) || "");
    if (!/looot/i.test(tool)) continue;
    calls += 1;
    const text = typeof step.observation === "string" ? step.observation : JSON.stringify(step.observation ?? "");
    for (const m of text.matchAll(/"actualCost"\s*:\s*([0-9.eE+-]+)/g)) {
      const n = Number(m[1]);
      if (Number.isFinite(n)) usd += n;
    }
  }
  return { looot_calls: calls, looot_cost_usd: Number(usd.toFixed(6)) };
}

const companies = $("Companies to research").all().map((i) => i.json);
const briefs = $input.all().map((i) => i.json);
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
let total = 0;
const sections = briefs.map((b, i) => {
  const c = companies[i] || {};
  const cost = agentCost(b);
  total += cost.looot_cost_usd;
  const when = (c.meetings || []).map((m) => `${esc(m.title)} (${esc(m.start)})`).join(", ");
  const text = typeof b.output === "string" ? b.output : JSON.stringify(b.output ?? "");
  return `<h3>${esc(c.domain)}</h3><p><i>${when}</i></p><div>${esc(text).replace(/\n/g, "<br>")}</div>`;
});
if (!sections.length) return [];
const html = `<p>Briefs for today's calls.</p>${sections.join("<hr>")}<p style="color:#666">Data cost: $${total.toFixed(4)} in looot calls.</p>`;
return [{ json: { subject: `Call prep: ${companies.length} compan${companies.length === 1 ? "y" : "ies"} today`, html, looot_cost_usd: Number(total.toFixed(6)) } }];
